export const MONUMENTS = JSON.parse("[{\"id\":\"n5825777993\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. М. Шульцу\",\"x\":-2711.9,\"z\":-1364,\"subject\":\"Q4527628\",\"inscription\":\"В этом здании с 1972 по 2006 год работал выдающийся российский учёный-физиохимик академик Михаил Михайлович Шульц\"},{\"id\":\"n5825777994\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. Н. Качалову\",\"x\":-2714.8,\"z\":-1365,\"subject\":\"Q4217895\",\"inscription\":\"Здесь работал с 1948 по 1961 год член-корреспондент Академии Наук СССР Николай Николаевич Качалов - крупный учёный, внёсший выдающийся вклад в развитие технологии изготовления оптического и художественного стекла\"},{\"id\":\"n5825777995\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. А. Торопову\",\"x\":-2719.9,\"z\":-1366.6,\"subject\":\"Q4461227\",\"inscription\":\"В этом здании, в институте химии силикатов Академии наук СССР, с 1948 по 1968 год работал крупный советский учёный, член-корреспондент Академии наук СССР Никита Александрович Торопов\"},{\"id\":\"n5825777996\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. В. Гребенщикову\",\"x\":-2726.6,\"z\":-1368.8,\"subject\":\"Q4148272\",\"inscription\":\"Здесь работал с 1948 по 1953 г. академик Илья Васильевич Гребенщиков - крупный советский учёный, организатор Института химии силикатов АН СССР\"},{\"id\":\"n7810340273\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Полканову\",\"x\":-2652.9,\"z\":-1344.8,\"subject\":\"Q12141775\",\"inscription\":\"Здесь с 1950 по 1963 г. работал выдающийся геолог и петрограф, академик Александр Алексеевич Полканов (1888–1963)\"},{\"id\":\"n8165689057\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. Г. Левицкому\",\"x\":-3598.7,\"z\":-1398.7,\"subject\":\"Q556681\",\"inscription\":\"В этом доме в 1792-1822 годах жил и работал выдающийся русский художник Дмитрий Григорьевич Левицкий\"},{\"id\":\"n8765492605\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Баррикадам против полиции царского самодержавия\",\"x\":-3999.5,\"z\":-1380.5,\"inscription\":\"У этого дома в январе 1905 года рабочими были устроены баррикады против полиции царского самодержавия.\"},{\"id\":\"n8769513424\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. Д. Кузьминскому\",\"x\":-4139.2,\"z\":-1349.6,\"subject\":\"Q18044510\",\"inscription\":\"Здесь в 1893 г. жил изобретатель газовой турбины Павел Дмитриевич Кузьминский\"},{\"id\":\"n8769559548\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Лишеву\",\"x\":-4150.2,\"z\":-1368.8,\"subject\":\"Q4264492\",\"inscription\":\"Здесь жил с 1917 по 1960 г. скульптор В. В. Лишев\"}]");
